void copy_buffer(char* dest, const char* src, size_t count) {
  memcpy(dest, src, count);
}

template <typename T>
T read_element_at_index(const T* data, size_t index) {
  return data[index];
}

char* get_data_after_release(const char* input, size_t len) {
  char* buffer = new char[len + 1];
  memcpy(buffer, input, len);
  buffer[len] = '\0';
  delete[] buffer;
  return buffer;
}

void fill_array_with_value(int* arr, size_t size, int value, size_t count) {
  for (size_t i = 0; i < count; ++i) {
    arr[i] = value;
  }
}
